Looking at the demos, I see the pattern fills outward from the feature (wall) column/row, with each position at distance k from the feature getting pattern[(k-1) % len(pattern)], where pattern is extracted from the source terminal (read bottom-to-top for columns, left-to-right for rows).

For the test input:
- Source: Col 6 [9,3,5,7,6,2,8,4], read bottom-to-top → pattern [4,8,2,6,7,5,3,9]
- Feature: Col 5 (all 6s)
- Fill cols: 4,3,2,1,0 (all distance k=1,2,3,4,5 from feature)
- Fill values: [pattern[0], pattern[1], pattern[2], pattern[3], pattern[4]] = [4,8,2,6,7]

```python
def transform(grid):
    h = len(grid)
    w = len(grid[0])
    result = [row[:] for row in grid]

    has_varied_col = any(len(set(grid[r][c] for r in range(h))) > 1 for c in range(w))

    if has_varied_col:
        # Column-major
        source_c = next(c for c in range(w) if len(set(grid[r][c] for r in range(h))) > 1)
        pattern = [grid[h - 1 - r][source_c] for r in range(h)]

        feature_c = -1
        for dc in [1, -1]:
            c = source_c + dc
            if 0 <= c < w and len(set(grid[r][c] for r in range(h))) == 1:
                feature_c = c
                break

        for c in range(w):
            if c != source_c and c != feature_c:
                if c < feature_c:
                    k = feature_c - c
                else:
                    k = c - feature_c
                fill_val = pattern[(k - 1) % len(pattern)]
                for r in range(h):
                    result[r][c] = fill_val
    else:
        # Row-major
        source_r = next(r for r in range(h) if len(set(grid[r][c] for c in range(w))) > 1)
        pattern = [grid[source_r][c] for c in range(w)]

        feature_r = -1
        for dr in [1, -1]:
            r = source_r + dr
            if 0 <= r < h and len(set(grid[r][c] for c in range(w))) == 1:
                feature_r = r
                break

        for r in range(h):
            if r != source_r and r != feature_r:
                if r < feature_r:
                    k = feature_r - r
                else:
                    k = r - feature_r
                fill_val = pattern[(k - 1) % len(pattern)]
                for c in range(w):
                    result[r][c] = fill_val

    return result
